"""Reads the nightly export."""
import pandas as pd

from . import config


def read_orders(cfg):
    path = config.data_dir(cfg) / "orders.csv.gz"
    df = pd.read_csv(path, parse_dates=["placed_at"], dtype={"order_id": str, "line_id": str},
                     on_bad_lines="warn")
    df["sku"] = df["sku"].astype(str)
    return df


def read_returns(cfg):
    path = config.data_dir(cfg) / "returns.csv.gz"
    df = pd.read_csv(path, parse_dates=["raised_at"], dtype={"credit_id": str},
                     on_bad_lines="warn")
    df["sku"] = df["sku"].astype(str)
    return df


def read_catalogue(cfg):
    path = config.data_dir(cfg) / "catalogue.csv"
    df = pd.read_csv(path, parse_dates=["first_listed"])
    df["sku"] = df["sku"].astype(str)
    return df


def read_accounts(cfg):
    path = config.data_dir(cfg) / "accounts.csv"
    return pd.read_csv(path, parse_dates=["first_order_at"])
"""Run configuration."""
from pathlib import Path

import yaml


class Config(dict):
    @property
    def paths(self):
        return self["paths"]

    @property
    def windows(self):
        return self["windows"]


def load(path):
    with open(path) as fh:
        cfg = Config(yaml.safe_load(fh))
    root = Path(path).resolve().parents[1]
    cfg["_root"] = root
    return cfg


def data_dir(cfg):
    return Path(cfg["_root"]) / cfg["paths"]["data_dir"]
"""Sanity checks run before the scores are published."""


class ValidationError(Exception):
    pass


def check(scores):
    if len(scores) == 0:
        raise ValidationError("no rows were scored")
    values = scores["risk_score"].values
    if any(v != v for v in values):
        raise ValidationError("risk_score contains nulls")
    bad = [v for v in values if v < 0.0 or v > 1.0]
    if bad:
        raise ValidationError("risk_score outside [0, 1] on %d rows" % len(bad))
    return True
"""Run summary written beside the scores."""
import json

import numpy as np

from . import drift


def _feature_spread(fit_df, columns):
    spread = {}
    for name, series in fit_df[columns].items():
        spread[name] = round(float(series.std()), 6)
    return spread


def summarise(scores, fit_df, score_df, cfg, columns):
    return {
        "rows_scored": int(len(scores)),
        "rows_fitted": int(len(fit_df)),
        "held": int(scores["hold"].sum()),
        "hold_rate": round(float(scores["hold"].mean()), 6),
        "mean_score": round(float(scores["risk_score"].mean()), 6),
        "score_window": cfg["windows"]["score"],
        "fit_window": cfg["windows"]["fit"],
        "feature_spread": _feature_spread(fit_df, columns),
        "month_on_month": drift.month_on_month(scores),
    }


def write(path, payload):
    with open(path, "w") as fh:
        json.dump(payload, fh, indent=2, sort_keys=True)
        fh.write("\n")

