def ewm_last(x, a, adjust=True):
    x=np.asarray(x,dtype=float)
    if adjust:
        w=(1-a)**np.arange(len(x)-1,-1,-1)
        return (w*x).sum()/w.sum()
    s=x[0]
    for v in x[1:]: s=(1-a)*s+a*v
    return s
def ewm_mean(x,a,adjust=True):
    x=np.asarray(x,dtype=float); out=[]
    if adjust:
        num=0.0;den=0.0
        for i,v in enumerate(x):
            num=num*(1-a)+v; den=den*(1-a)+1
            out.append(num/den)
    else:
        s=x[0]; out=[s]
        for v in x[1:]:
            s=(1-a)*s+a*v; out.append(s)
    return np.mean(out)
alphas=np.concatenate([np.linspace(0.01,0.99,99)])
defs={}
for sku,(d,v) in multi.items():
