from scipy.optimize import brentq
series=pickle.load(open('/tmp/x/series.pkl','rb'))
end=pd.Timestamp('2010-11-30'); lo=pd.Timestamp('2009-12-01')
# exact small cases
names=['85035b','84985a','DCGSSGIRL','DCGSSBOY','90181A','90187B','22830','90118','84993a']
cases={n:series[n] for n in names}
def pred(d, alpha, grid, stat, adjust):
    if grid=='fe': idx=pd.date_range(d.index.min(),end,freq='D')
    elif grid=='full': idx=pd.date_range(lo,end,freq='D')
    else: idx=pd.date_range(d.index.min(),d.index.max(),freq='D')
    dd=d.reindex(idx,fill_value=0.0)
    e=dd.ewm(alpha=alpha,adjust=adjust).mean()
    return e.iloc[-1] if stat=='last' else e.mean()
# for each config, solve alpha per case; consistent config -> same alpha across cases
for grid in ['fe','full','fl']:
    for stat in ['last','mean']:
        for adjust in [True,False]:
            sols={}
            for n,(d,v) in cases.items():
                f=lambda a: pred(d,a,grid,stat,adjust)-v
                try:
                    lovals=f(1e-4); hivals=f(0.9999)
                    if lovals*hivals<0:
                        sols[n]=round(brentq(f,1e-4,0.9999,xtol=1e-6),5)
                    else:
                        # scan
                        aa=np.linspace(1e-4,0.9999,60)
                        vals=[f(a) for a in aa]
                        r=None
                        for i in range(len(aa)-1):
                            if vals[i]*vals[i+1]<0:
                                r=brentq(f,aa[i],aa[i+1]); break
                        sols[n]=round(r,5) if r else None
                except Exception as ex:
                    sols[n]=str(ex)[:20]
